"use client";

import React from 'react';
import { DashboardCard } from '@/components/client/DashboardCard';
import {
    Calendar,
    User,
    Scissors,
    Clock,
    ArrowRight,
    History,
    TicketPercent,
    Star,
    Sparkles,
    CalendarPlus
} from 'lucide-react';
import { Button } from '@/components/ui/Button';
import Link from 'next/link';

export default function ClientDashboard() {
    return (
        <div className="space-y-10 animate-fade-in-up">
            {/* Quick Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                <DashboardCard
                    title="Próximo Atendimento"
                    value="15/09/2026"
                    subtitle="Terça-feira"
                    icon={<Calendar className="w-6 h-6" />}
                />
                <DashboardCard
                    title="Barbeiro Escolhido"
                    value="Marcelo Silva"
                    subtitle="Especialista em Navalhados"
                    icon={<User className="w-6 h-6" />}
                />
                <DashboardCard
                    title="Serviço Agendado"
                    value="Combo CBS"
                    subtitle="Corte + Barba + Sobrancelha"
                    icon={<Scissors className="w-6 h-6" />}
                />
                <DashboardCard
                    title="Horário"
                    value="10:30"
                    subtitle="Duração aprox: 60 min"
                    icon={<Clock className="w-6 h-6" />}
                />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Left Column: Actions and Promotions */}
                <div className="lg:col-span-2 space-y-8">
                    {/* Welcome Banner */}
                    <div className="relative overflow-hidden bg-gradient-to-br from-[var(--color-dark-card)] to-black border border-[var(--color-dark-border)] rounded-3xl p-8 lg:p-10">
                        <div className="absolute top-0 right-0 w-64 h-64 bg-[var(--color-primary-gold)]/5 rounded-full blur-3xl -mr-20 -mt-20" />

                        <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
                            <div>
                                <h3 className="text-3xl font-bold text-white mb-2 tracking-tight">Pronto para seu <span className="text-[var(--color-primary-gold)]">novo visual?</span></h3>
                                <p className="text-gray-400 mb-6 max-w-md">Garanta seu horário com os melhores barbers da região. Experiência premium, ambiente climatizado e café especial.</p>
                                <Link href="/client/schedule">
                                    <Button size="lg" className="w-full md:w-auto h-14 px-10 gap-2 text-sm font-black tracking-widest bg-[var(--color-primary-gold)] shadow-[0_10px_30px_rgba(212,175,55,0.2)]">
                                        <CalendarPlus className="w-5 h-5" /> AGENDAR AGORA
                                    </Button>
                                </Link>
                            </div>
                            <div className="flex-shrink-0">
                                <div className="w-32 h-32 rounded-3xl border-2 border-[var(--color-primary-gold)]/20 rotate-12 flex items-center justify-center p-2">
                                    <div className="w-full h-full bg-[var(--color-primary-gold)]/10 rounded-2xl flex items-center justify-center">
                                        <Sparkles className="w-12 h-12 text-[var(--color-primary-gold)]" />
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Recent History Preview */}
                    <div className="space-y-4">
                        <div className="flex items-center justify-between px-2">
                            <h4 className="flex items-center gap-2 text-lg font-bold">
                                <History className="w-5 h-5 text-[var(--color-primary-gold)]" /> Histórico Recente
                            </h4>
                            <Link href="/client/history" className="text-xs text-[var(--color-primary-gold)] hover:underline flex items-center gap-1">Ver todos <ArrowRight className="w-3 h-3" /></Link>
                        </div>
                        <div className="space-y-3">
                            {[
                                { date: '28/08', item: 'Combo CBS', price: 'R$ 85,00', barber: 'Marcelo Silva' },
                                { date: '12/08', item: 'Corte Degradê', price: 'R$ 55,00', barber: 'Felipe Santos' },
                            ].map((item, i) => (
                                <div key={i} className="flex items-center justify-between p-5 bg-[var(--color-dark-card)] border border-[var(--color-dark-border)] rounded-2xl hover:bg-white/5 transition-all">
                                    <div className="flex items-center gap-4">
                                        <div className="text-center w-12 border-r border-[var(--color-dark-border)] pr-4">
                                            <p className="text-xs font-bold text-white">{item.date.split('/')[0]}</p>
                                            <p className="text-[10px] text-gray-500 uppercase tracking-tighter">AGO</p>
                                        </div>
                                        <div>
                                            <p className="font-bold text-sm text-white">{item.item}</p>
                                            <p className="text-[10px] text-gray-500 font-medium">Barbeiro: {item.barber}</p>
                                        </div>
                                    </div>
                                    <span className="text-sm font-bold text-[var(--color-primary-gold)]">{item.price}</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Right Column: Promotions and Quick Actions */}
                <div className="space-y-8">
                    {/* Promotions Section */}
                    <div className="space-y-4">
                        <h4 className="px-2 flex items-center gap-2 text-lg font-bold">
                            <TicketPercent className="w-5 h-5 text-[var(--color-primary-gold)]" /> Promoções
                        </h4>
                        <div className="space-y-4">
                            <div className="group relative overflow-hidden p-6 bg-gradient-to-br from-[#1A1100] to-black border border-[#3D2C00] rounded-3xl">
                                <div className="relative z-10">
                                    <span className="inline-block px-3 py-1 bg-[var(--color-primary-gold)] text-black text-[9px] font-black uppercase rounded-full mb-4">Combo da Semana</span>
                                    <h5 className="text-xl font-bold mb-1">Corte + Barba</h5>
                                    <p className="text-gray-500 text-xs mb-4">Hidratação grátis incluída.</p>
                                    <p className="text-3xl font-black text-[var(--color-primary-gold)] mb-1">R$ 69,90</p>
                                    <p className="text-[10px] text-gray-600">Válido Ter-Qui</p>
                                </div>
                                <Sparkles className="absolute bottom-4 right-4 w-12 h-12 text-[var(--color-primary-gold)] opacity-10 group-hover:scale-125 transition-transform" />
                            </div>
                        </div>
                    </div>

                    {/* Quick Review */}
                    <div className="bg-[var(--color-dark-card)] border border-[var(--color-dark-border)] rounded-3xl p-6">
                        <h5 className="text-sm font-bold flex items-center gap-2 mb-4 italic">
                            <Star className="w-4 h-4 text-[var(--color-primary-gold)]" /> Último Corregedor
                        </h5>
                        <p className="text-xs text-gray-400 mb-6 italic">"O trabalho do Marcelo ficou excelente, super recomendo!"</p>
                        <div className="flex gap-1 text-[var(--color-primary-gold)] mb-4">
                            {[1, 2, 3, 4, 5].map(s => <Star key={s} className="w-4 h-4 fill-current" />)}
                        </div>
                        <Link href="/client/rate">
                            <Button variant="outline" size="sm" className="w-full text-[10px] font-bold tracking-widest border-white/10 text-white/50 hover:text-white hover:border-[var(--color-primary-gold)]/50">
                                AVALIAR ÚLTIMO SERVIÇO
                            </Button>
                        </Link>
                    </div>
                </div>
            </div>
        </div>
    );
}
